-- Safety-critical flags for a microbiology culture request, independent of the axes.

CREATE TABLE microbiology_culture_test_request_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    microbiology_culture_test_request_grade_id UUID NOT NULL
        REFERENCES microbiology_culture_test_request_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(40) NOT NULL DEFAULT ''
        CHECK (category IN (
            'suspected-sepsis-stat',
            'blood-culture-before-antibiotics',
            'specimen-not-collected',
            'missing-clinical-details',
            'missing-indication',
            'no-test-selected',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_microbiology_culture_test_request_grade_flag_grade_id
    ON microbiology_culture_test_request_grade_flag(microbiology_culture_test_request_grade_id);

CREATE TRIGGER trigger_microbiology_culture_test_request_grade_flag_updated_at
